import os,json,urllib.parse
def walk(d):
    out=[]
    for r,_,fs in os.walk(d):
        for f in fs:
            if f.startswith('.'):continue
            out.append(os.path.join(r,f).replace(os.sep,'/'))
    return sorted(out)
